export const SettlementStatus = {
  APPROVED: 'APROBADA',
  REJECTED: 'RECHAZADA',
  PENDING_APPROVAL: 'PENDIENTE_APROBACION',
} as const;
export type SettlementStatusValue = (typeof SettlementStatus)[keyof typeof SettlementStatus];

export const ReasonCode = {
  POLICY_NOT_IN_FORCE: 'POLIZA_NO_VIGENTE',
  OUT_OF_VALIDITY: 'FUERA_DE_VIGENCIA',
  LATE_REPORT: 'DENUNCIA_EXTEMPORANEA',
  COVERAGE_NOT_CONTRACTED: 'COBERTURA_NO_CONTRATADA',
  WAITING_PERIOD: 'EN_PERIODO_CARENCIA',
  PREMIUM_IN_ARREARS: 'PRIMA_EN_MORA',
  BELOW_DEDUCTIBLE: 'BAJO_DEDUCIBLE',
  INSURED_SUM_EXHAUSTED: 'SUMA_ASEGURADA_AGOTADA',
  FRAUD_SUSPICION: 'SOSPECHA_FRAUDE',
  AUTO_LIMIT_EXCEEDED: 'SUPERA_TOPE_AUTOMATICO',
  AUTOMATIC_SETTLEMENT: 'LIQUIDACION_AUTOMATICA',
} as const;
export type ReasonCodeValue = (typeof ReasonCode)[keyof typeof ReasonCode];

export const Mark = {
  VIP_ARREARS_TOLERANCE: 'TOLERANCIA_MORA_VIP',
  COVERAGE_LIMIT: 'LIMITE_COBERTURA',
  MINIMUM_DEDUCTIBLE: 'DEDUCIBLE_MINIMO',
  VIP_DISCOUNT: 'DESCUENTO_VIP',
  CLAIM_FREQUENCY_PENALTY: 'PENALIZACION_SINIESTRALIDAD',
  INSURED_SUM_CAP: 'TOPE_SUMA_ASEGURADA',
  WITHHOLDING_APPLIED: 'RETENCION_APLICADA',
} as const;

export const ClaimFinalStatus = {
  LIQUIDATED: 'LIQUIDADO',
  REJECTED: 'RECHAZADO',
  PENDING_REVIEW: 'PENDIENTE_REVISION',
} as const;
export type ClaimFinalStatusValue = (typeof ClaimFinalStatus)[keyof typeof ClaimFinalStatus];

export const ClaimStatus = { REGISTERED: 'REGISTRADO' } as const;
export const PolicyStatus = { IN_FORCE: 'VIGENTE' } as const;
export const PolicyBranch = { LIFE: 'VIDA' } as const;
export const CustomerCategory = { VIP: 'VIP' } as const;
export const DeductibleType = { FIXED: 'FIJO', PERCENTAGE: 'PORCENTAJE' } as const;

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, month: number): number {
  if (month === 2) {
    return isLeapYear(year) ? 29 : 28;
  }
  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

function isValidCalendarDate(year: number, month: number, day: number): boolean {
  return month >= 1 && month <= 12 && day >= 1 && day <= daysInMonth(year, month);
}

function toEpochDay(year: number, month: number, day: number): number {
  const y = month <= 2 ? year - 1 : year;
  const era = Math.floor(y / 400);
  const yearOfEra = y - era * 400;
  const shiftedMonth = month > 2 ? month - 3 : month + 9;
  const dayOfYear = Math.floor((153 * shiftedMonth + 2) / 5) + day - 1;
  const dayOfEra = yearOfEra * 365 + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100) + dayOfYear;
  return era * 146097 + dayOfEra - 719468;
}

/** Fecha de calendario sin hora. Equivale a TRUNC(date) del legacy. */
export class DateOnly {
  readonly epochDay: number;

  private constructor(epochDay: number) {
    this.epochDay = epochDay;
  }

  static fromEpochDay(epochDay: number): DateOnly {
    return new DateOnly(epochDay);
  }

  /** Acepta YYYY-MM-DD, con una parte horaria opcional que se ignora (TRUNC). */
  static parse(text: string): DateOnly | null {
    const match = /^(\d{4})-(\d{2})-(\d{2})(?:[T ].*)?$/.exec(text);
    if (match === null) {
      return null;
    }
    const year = parseInt(match[1], 10);
    const month = parseInt(match[2], 10);
    const day = parseInt(match[3], 10);
    if (!isValidCalendarDate(year, month, day)) {
      return null;
    }
    return new DateOnly(toEpochDay(year, month, day));
  }

  /** Días enteros de this menos other. */
  daysSince(other: DateOnly): number {
    return this.epochDay - other.epochDay;
  }

  isBefore(other: DateOnly): boolean {
    return this.epochDay < other.epochDay;
  }

  isAfter(other: DateOnly): boolean {
    return this.epochDay > other.epochDay;
  }
}

/** Marcas de ajuste acumuladas, inmutable. */
export class Observations {
  private readonly marks: readonly string[];

  private constructor(marks: readonly string[]) {
    this.marks = marks;
  }

  static empty(): Observations {
    return new Observations([]);
  }

  /**
   * Añade una marca al final, respetando el orden de aplicación.
   * @rule R-021
   */
  add(mark: string): Observations {
    return new Observations([...this.marks, mark]);
  }

  /** @rule R-021 */
  addIfPresent(mark: string | null): Observations {
    return mark === null ? this : this.add(mark);
  }

  /**
   * Marcas separadas por ';', o null si no hubo ninguna (NULL del legacy).
   * @rule R-021
   */
  toNullable(): string | null {
    return this.marks.length === 0 ? null : this.marks.join(';');
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { DateOnly } from './DateOnly.ts';

export interface ClaimFacts {
  readonly status: string;
  readonly occurrenceDate: DateOnly;
  readonly reportDate: DateOnly;
  readonly processDate: DateOnly;
  readonly claimedAmount: Decimal;
}

export interface PolicyFacts {
  readonly status: string;
  readonly branch: string;
  readonly startDate: DateOnly;
  readonly endDate: DateOnly;
  readonly sumInsured: Decimal;
  readonly deductibleType: string;
  readonly deductibleValue: Decimal;
  readonly pendingPremium: Decimal;
  readonly priorLiquidatedClaims365d: number;
  readonly totalIndemnified: Decimal;
}

export interface CoverageFacts {
  readonly code: string;
  readonly found: boolean;
  readonly limit: Decimal;
  readonly percentage: Decimal;
  readonly waitingDays: number;
}

/** Hechos de entrada de una liquidación. */
export interface ClaimCase {
  readonly claimId: string;
  readonly customerCategory: string;
  readonly claim: ClaimFacts;
  readonly policy: PolicyFacts;
  readonly coverage: CoverageFacts;
}

/** Error de negocio que se devuelve como dato (no se lanza). */
export class BusinessFailure {
  readonly code: string;
  readonly message: string;

  constructor(code: string, message: string) {
    this.code = code;
    this.message = message;
  }

  /** @rule R-001 */
  static claimNotRegistered(claimId: string, currentStatus: string): BusinessFailure {
    return new BusinessFailure(
      'ORA-20001',
      `El siniestro ${claimId} no esta en estado REGISTRADO (${currentStatus})`,
    );
  }

  /** @rule R-023 */
  static missingParameter(parameterCode: string): BusinessFailure {
    return new BusinessFailure('ORA-20010', `Parametro no definido: ${parameterCode}`);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { BusinessFailure } from '../exceptions/BusinessFailure.ts';

export const ParameterCode = {
  MAX_REPORT_DAYS: 'DIAS_MAX_DENUNCIA',
  MAX_REPORT_DAYS_LIFE: 'DIAS_MAX_DENUNCIA_VIDA',
  MINIMUM_DEDUCTIBLE: 'DEDUCIBLE_MINIMO',
  VIP_DEDUCTIBLE_DISCOUNT_PCT: 'PCT_DESCUENTO_DED_VIP',
  VIP_ARREARS_TOLERANCE: 'TOLERANCIA_MORA_VIP',
  MAX_ANNUAL_CLAIMS: 'MAX_SINIESTROS_ANUAL',
  CLAIM_FREQUENCY_PENALTY_PCT: 'PCT_PENALIZACION_SINIEST',
  WITHHOLDING_THRESHOLD: 'UMBRAL_RETENCION',
  WITHHOLDING_RATE_PCT: 'TASA_RETENCION',
  AUTO_APPROVAL_LIMIT: 'TOPE_AUTO_APROBACION',
  FRAUD_ALERT_DAYS: 'DIAS_ALERTA_FRAUDE',
  FRAUD_ALERT_PCT: 'PCT_ALERTA_FRAUDE',
} as const;

const REQUIRED_CODES: readonly string[] = Object.values(ParameterCode);

export class ParameterResolution {
  readonly parameters: BusinessParameters | null;
  readonly failure: BusinessFailure | null;

  constructor(parameters: BusinessParameters | null, failure: BusinessFailure | null) {
    this.parameters = parameters;
    this.failure = failure;
  }
}

/** Parámetros de negocio tipados. */
export class BusinessParameters {
  readonly maxReportDays: Decimal;
  readonly maxReportDaysLife: Decimal;
  readonly minimumDeductible: Decimal;
  readonly vipDeductibleDiscountPct: Decimal;
  readonly vipArrearsTolerance: Decimal;
  readonly maxAnnualClaims: Decimal;
  readonly claimFrequencyPenaltyPct: Decimal;
  readonly withholdingThreshold: Decimal;
  readonly withholdingRatePct: Decimal;
  readonly autoApprovalLimit: Decimal;
  readonly fraudAlertDays: Decimal;
  readonly fraudAlertPct: Decimal;

  private constructor(values: ReadonlyMap<string, Decimal>) {
    this.maxReportDays = values.get(ParameterCode.MAX_REPORT_DAYS) as Decimal;
    this.maxReportDaysLife = values.get(ParameterCode.MAX_REPORT_DAYS_LIFE) as Decimal;
    this.minimumDeductible = values.get(ParameterCode.MINIMUM_DEDUCTIBLE) as Decimal;
    this.vipDeductibleDiscountPct = values.get(ParameterCode.VIP_DEDUCTIBLE_DISCOUNT_PCT) as Decimal;
    this.vipArrearsTolerance = values.get(ParameterCode.VIP_ARREARS_TOLERANCE) as Decimal;
    this.maxAnnualClaims = values.get(ParameterCode.MAX_ANNUAL_CLAIMS) as Decimal;
    this.claimFrequencyPenaltyPct = values.get(ParameterCode.CLAIM_FREQUENCY_PENALTY_PCT) as Decimal;
    this.withholdingThreshold = values.get(ParameterCode.WITHHOLDING_THRESHOLD) as Decimal;
    this.withholdingRatePct = values.get(ParameterCode.WITHHOLDING_RATE_PCT) as Decimal;
    this.autoApprovalLimit = values.get(ParameterCode.AUTO_APPROVAL_LIMIT) as Decimal;
    this.fraudAlertDays = values.get(ParameterCode.FRAUD_ALERT_DAYS) as Decimal;
    this.fraudAlertPct = values.get(ParameterCode.FRAUD_ALERT_PCT) as Decimal;
  }

  /**
   * Verifica que existan todos los parámetros necesarios; si falta alguno devuelve ORA-20010.
   * @rule R-023
   */
  static resolve(values: ReadonlyMap<string, Decimal>): ParameterResolution {
    const missing = REQUIRED_CODES.find((code) => !values.has(code));
    if (missing !== undefined) {
      return new ParameterResolution(null, BusinessFailure.missingParameter(missing));
    }
    return new ParameterResolution(new BusinessParameters(values), null);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { Observations } from './Observations.ts';
import type { ReasonCodeValue } from './vocabulary.ts';

/** Importe intermedio con sus observaciones acumuladas. */
export class Adjusted {
  readonly amount: Decimal;
  readonly observations: Observations;

  constructor(amount: Decimal, observations: Observations) {
    this.amount = amount;
    this.observations = observations;
  }
}

/** Rechazo de negocio con las observaciones acumuladas hasta ese punto. */
export class Rejection {
  readonly reason: ReasonCodeValue;
  readonly observations: Observations;

  constructor(reason: ReasonCodeValue, observations: Observations) {
    this.reason = reason;
    this.observations = observations;
  }
}

export class CalculatedAmounts {
  readonly base: Decimal;
  readonly deductible: Decimal;
  readonly covered: Decimal;
  readonly withholding: Decimal;
  readonly net: Decimal;
  readonly observations: Observations;

  constructor(
    base: Decimal,
    deductible: Decimal,
    covered: Decimal,
    withholding: Decimal,
    net: Decimal,
    observations: Observations,
  ) {
    this.base = base;
    this.deductible = deductible;
    this.covered = covered;
    this.withholding = withholding;
    this.net = net;
    this.observations = observations;
  }
}

import { ClaimFinalStatus, SettlementStatus } from './vocabulary.ts';
import type { ClaimFinalStatusValue, SettlementStatusValue } from './vocabulary.ts';

const FINAL_STATUS_BY_SETTLEMENT: Readonly<Record<SettlementStatusValue, ClaimFinalStatusValue>> = {
  [SettlementStatus.APPROVED]: ClaimFinalStatus.LIQUIDATED,
  [SettlementStatus.REJECTED]: ClaimFinalStatus.REJECTED,
  [SettlementStatus.PENDING_APPROVAL]: ClaimFinalStatus.PENDING_REVIEW,
};

/**
 * Estado final del siniestro según el estado de la liquidación.
 * @rule R-020
 */
export function finalClaimStatusFor(status: SettlementStatusValue): ClaimFinalStatusValue {
  return FINAL_STATUS_BY_SETTLEMENT[status];
}

import { Decimal } from '../shared/decimal.ts';

export const ZERO_AMOUNT: Decimal = Decimal.of('0.00');
const HUNDRED: Decimal = Decimal.of(100);

/**
 * ROUND(amount * percentage / 100, 2) con la mitad hacia arriba.
 * @rule R-022
 */
export function roundedPercentOf(amount: Decimal, percentage: Decimal): Decimal {
  return amount.times(percentage).dividedBy(HUNDRED, 2, 'HALF_UP');
}

/**
 * ROUND(amount * (100 - percentage) / 100, 2) con la mitad hacia arriba.
 * @rule R-022
 */
export function roundedComplementOf(amount: Decimal, percentage: Decimal): Decimal {
  return roundedPercentOf(amount, HUNDRED.minus(percentage));
}

/**
 * Ajusta un importe a escala 2 (NUMBER(14,2)).
 * @rule R-022
 */
export function toMoney(amount: Decimal): Decimal {
  return amount.setScale(2, 'HALF_UP');
}

import type { ClaimCase } from '../model/ClaimCase.ts';
import { ClaimStatus } from '../model/vocabulary.ts';

export class RegisteredClaimSpecification {
  /**
   * Solo se liquida un siniestro en estado REGISTRADO.
   * @rule R-001
   */
  isSatisfiedBy(claim: ClaimCase): boolean {
    return claim.claim.status === ClaimStatus.REGISTERED;
  }
}

import type { ClaimCase } from '../model/ClaimCase.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { Decimal } from '../shared/decimal.ts';
import { roundedPercentOf } from '../services/rounding.ts';

export class FraudAlertSpecification {
  /**
   * Ocurrencia dentro de los primeros DIAS_ALERTA_FRAUDE días (inclusive) y reclamo >= PCT_ALERTA_FRAUDE% del límite.
   * @rule R-017
   */
  isSatisfiedBy(claim: ClaimCase, parameters: BusinessParameters): boolean {
    return this.isEarlyInPolicy(claim, parameters) && this.isHighClaim(claim, parameters);
  }

  /** @rule R-017 */
  private isEarlyInPolicy(claim: ClaimCase, parameters: BusinessParameters): boolean {
    const daysSinceStart = claim.claim.occurrenceDate.daysSince(claim.policy.startDate);
    return Decimal.of(daysSinceStart).lte(parameters.fraudAlertDays);
  }

  /** @rule R-017 */
  private isHighClaim(claim: ClaimCase, parameters: BusinessParameters): boolean {
    const threshold = roundedPercentOf(claim.coverage.limit, parameters.fraudAlertPct);
    return claim.claim.claimedAmount.gte(threshold);
  }
}

import type { ReasonCodeValue } from '../model/vocabulary.ts';

/** Resultado de una regla de elegibilidad: pasa (con marca opcional) o rechaza. */
export class EligibilityVerdict {
  readonly rejectionReason: ReasonCodeValue | null;
  readonly mark: string | null;

  private constructor(rejectionReason: ReasonCodeValue | null, mark: string | null) {
    this.rejectionReason = rejectionReason;
    this.mark = mark;
  }

  static passed(): EligibilityVerdict {
    return new EligibilityVerdict(null, null);
  }

  static passedWithMark(mark: string): EligibilityVerdict {
    return new EligibilityVerdict(null, mark);
  }

  static rejected(reason: ReasonCodeValue): EligibilityVerdict {
    return new EligibilityVerdict(reason, null);
  }
}

import type { ClaimCase } from '../model/ClaimCase.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { EligibilityVerdict } from './EligibilityVerdict.ts';

export interface EligibilityRule {
  evaluate(claim: ClaimCase, parameters: BusinessParameters): EligibilityVerdict;
}

import type { ClaimCase } from '../model/ClaimCase.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { Decimal } from '../shared/decimal.ts';
import { EligibilityVerdict } from './EligibilityVerdict.ts';
import type { EligibilityRule } from './EligibilityRule.ts';
import { CustomerCategory, Mark, PolicyBranch, PolicyStatus, ReasonCode } from '../model/vocabulary.ts';
import { ZERO_AMOUNT } from '../services/rounding.ts';

export class PolicyInForceRule implements EligibilityRule {
  /** @rule R-002 */
  evaluate(claim: ClaimCase): EligibilityVerdict {
    return claim.policy.status === PolicyStatus.IN_FORCE
      ? EligibilityVerdict.passed()
      : EligibilityVerdict.rejected(ReasonCode.POLICY_NOT_IN_FORCE);
  }
}

export class OccurrenceWithinValidityRule implements EligibilityRule {
  /** Las fechas de inicio y fin cuentan como dentro de la vigencia. @rule R-003 */
  evaluate(claim: ClaimCase): EligibilityVerdict {
    const occurrence = claim.claim.occurrenceDate;
    const outside = occurrence.isBefore(claim.policy.startDate) || occurrence.isAfter(claim.policy.endDate);
    return outside ? EligibilityVerdict.rejected(ReasonCode.OUT_OF_VALIDITY) : EligibilityVerdict.passed();
  }
}

export class ReportingDeadlineRule implements EligibilityRule {
  /** Plazo máximo de denuncia por ramo; el último día del plazo se acepta. @rule R-004 */
  evaluate(claim: ClaimCase, parameters: BusinessParameters): EligibilityVerdict {
    const reportDays = Decimal.of(claim.claim.reportDate.daysSince(claim.claim.occurrenceDate));
    const maxDays = this.maxDaysFor(claim.policy.branch, parameters);
    return reportDays.gt(maxDays) ? EligibilityVerdict.rejected(ReasonCode.LATE_REPORT) : EligibilityVerdict.passed();
  }

  /** @rule R-004 */
  private maxDaysFor(branch: string, parameters: BusinessParameters): Decimal {
    return branch === PolicyBranch.LIFE ? parameters.maxReportDaysLife : parameters.maxReportDays;
  }
}

export class CoverageContractedRule implements EligibilityRule {
  /** @rule R-005 */
  evaluate(claim: ClaimCase): EligibilityVerdict {
    return claim.coverage.found
      ? EligibilityVerdict.passed()
      : EligibilityVerdict.rejected(ReasonCode.COVERAGE_NOT_CONTRACTED);
  }
}

export class WaitingPeriodRule implements EligibilityRule {
  /** @rule R-006 */
  evaluate(claim: ClaimCase): EligibilityVerdict {
    const daysSinceStart = claim.claim.occurrenceDate.daysSince(claim.policy.startDate);
    return daysSinceStart < claim.coverage.waitingDays
      ? EligibilityVerdict.rejected(ReasonCode.WAITING_PERIOD)
      : EligibilityVerdict.passed();
  }
}

export class PremiumArrearsRule implements EligibilityRule {
  /** Mora de prima con tolerancia VIP (hasta TOLERANCIA_MORA_VIP inclusive). @rule R-007 */
  evaluate(claim: ClaimCase, parameters: BusinessParameters): EligibilityVerdict {
    if (!claim.policy.pendingPremium.gt(ZERO_AMOUNT)) {
      return EligibilityVerdict.passed();
    }
    if (this.isTolerated(claim, parameters)) {
      return EligibilityVerdict.passedWithMark(Mark.VIP_ARREARS_TOLERANCE);
    }
    return EligibilityVerdict.rejected(ReasonCode.PREMIUM_IN_ARREARS);
  }

  /** @rule R-007 */
  private isTolerated(claim: ClaimCase, parameters: BusinessParameters): boolean {
    return (
      claim.customerCategory === CustomerCategory.VIP &&
      claim.policy.pendingPremium.lte(parameters.vipArrearsTolerance)
    );
  }
}

import type { ClaimCase } from '../model/ClaimCase.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { EligibilityRule } from '../eligibility/EligibilityRule.ts';
import { Observations } from '../model/Observations.ts';
import { Rejection } from '../model/StepResults.ts';

/** Evalúa las validaciones en orden fijo y se detiene en la primera que falla. */
export class EligibilityPolicy {
  private readonly rules: readonly EligibilityRule[];

  constructor(orderedRules: readonly EligibilityRule[]) {
    this.rules = orderedRules;
  }

  /**
   * Devuelve las observaciones acumuladas o el rechazo de la primera validación fallida.
   * El rechazo de validación no lleva observaciones (NULL).
   * @rule R-008
   */
  evaluate(claim: ClaimCase, parameters: BusinessParameters): Observations | Rejection {
    let observations = Observations.empty();
    for (const rule of this.rules) {
      const verdict = rule.evaluate(claim, parameters);
      if (verdict.rejectionReason !== null) {
        return new Rejection(verdict.rejectionReason, Observations.empty());
      }
      observations = observations.addIfPresent(verdict.mark);
    }
    return observations;
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { Observations } from '../model/Observations.ts';
import { Adjusted } from '../model/StepResults.ts';
import { Mark } from '../model/vocabulary.ts';
import { toMoney } from './rounding.ts';

export class BaseAmountCalculator {
  /**
   * Monto base = menor entre lo reclamado y el límite de cobertura.
   * @rule R-009
   */
  calculate(claimedAmount: Decimal, coverageLimit: Decimal, observations: Observations): Adjusted {
    if (claimedAmount.gt(coverageLimit)) {
      return new Adjusted(toMoney(coverageLimit), observations.add(Mark.COVERAGE_LIMIT));
    }
    return new Adjusted(toMoney(claimedAmount), observations);
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { Adjusted } from '../../model/StepResults.ts';

export interface DeductibleStrategy {
  calculate(base: Adjusted, deductibleValue: Decimal, parameters: BusinessParameters): Adjusted;
}

import type { Decimal } from '../../shared/decimal.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import { Adjusted } from '../../model/StepResults.ts';
import type { DeductibleStrategy } from './DeductibleStrategy.ts';
import { toMoney } from '../rounding.ts';

export class FixedDeductibleStrategy implements DeductibleStrategy {
  /**
   * Deducible fijo: el valor de la póliza, sin mínimo.
   * @rule R-010
   */
  calculate(base: Adjusted, deductibleValue: Decimal, _parameters?: BusinessParameters): Adjusted {
    return new Adjusted(toMoney(deductibleValue), base.observations);
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import { Adjusted } from '../../model/StepResults.ts';
import type { DeductibleStrategy } from './DeductibleStrategy.ts';
import { Mark } from '../../model/vocabulary.ts';
import { roundedPercentOf, toMoney } from '../rounding.ts';

export class PercentageDeductibleStrategy implements DeductibleStrategy {
  /**
   * Deducible porcentual sobre el monto base, redondeado a 2 decimales, con mínimo DEDUCIBLE_MINIMO.
   * @rule R-011
   * @rule R-022
   */
  calculate(base: Adjusted, deductibleValue: Decimal, parameters: BusinessParameters): Adjusted {
    const computed = roundedPercentOf(base.amount, deductibleValue);
    if (computed.lt(parameters.minimumDeductible)) {
      return new Adjusted(toMoney(parameters.minimumDeductible), base.observations.add(Mark.MINIMUM_DEDUCTIBLE));
    }
    return new Adjusted(computed, base.observations);
  }
}

import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import { Adjusted } from '../../model/StepResults.ts';
import { CustomerCategory, Mark } from '../../model/vocabulary.ts';
import { ZERO_AMOUNT, roundedComplementOf } from '../rounding.ts';

export class VipDeductibleDiscount {
  /**
   * Descuento VIP sobre el deducible (después del mínimo), solo si el deducible es mayor que cero.
   * @rule R-012
   * @rule R-022
   */
  apply(deductible: Adjusted, customerCategory: string, parameters: BusinessParameters): Adjusted {
    if (customerCategory !== CustomerCategory.VIP || !deductible.amount.gt(ZERO_AMOUNT)) {
      return deductible;
    }
    const discounted = roundedComplementOf(deductible.amount, parameters.vipDeductibleDiscountPct);
    return new Adjusted(discounted, deductible.observations.add(Mark.VIP_DISCOUNT));
  }
}

import type { ClaimCase } from '../../model/ClaimCase.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { Adjusted } from '../../model/StepResults.ts';
import { DeductibleType } from '../../model/vocabulary.ts';
import type { DeductibleStrategy } from './DeductibleStrategy.ts';
import type { VipDeductibleDiscount } from './VipDeductibleDiscount.ts';

export class DeductibleCalculator {
  private readonly fixed: DeductibleStrategy;
  private readonly percentage: DeductibleStrategy;
  private readonly vipDiscount: VipDeductibleDiscount;

  constructor(fixed: DeductibleStrategy, percentage: DeductibleStrategy, vipDiscount: VipDeductibleDiscount) {
    this.fixed = fixed;
    this.percentage = percentage;
    this.vipDiscount = vipDiscount;
  }

  /**
   * Selecciona la estrategia por tipo (FIJO o PORCENTAJE) y aplica el descuento VIP.
   * @rule R-010
   * @rule R-011
   * @rule R-012
   */
  calculate(claim: ClaimCase, base: Adjusted, parameters: BusinessParameters): Adjusted {
    const strategy = claim.policy.deductibleType === DeductibleType.FIXED ? this.fixed : this.percentage;
    const deductible = strategy.calculate(base, claim.policy.deductibleValue, parameters);
    return this.vipDiscount.apply(deductible, claim.customerCategory, parameters);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { Adjusted, Rejection } from '../model/StepResults.ts';
import { ReasonCode } from '../model/vocabulary.ts';
import { ZERO_AMOUNT, roundedPercentOf } from './rounding.ts';

export class CoveredAmountCalculator {
  /**
   * Cubierto = ROUND((base - deducible) * coverage_pct / 100, 2). Si es <= 0, rechaza por BAJO_DEDUCIBLE conservando observaciones.
   * @rule R-013
   * @rule R-022
   */
  calculate(base: Adjusted, deductible: Adjusted, coveragePct: Decimal): Adjusted | Rejection {
    const covered = roundedPercentOf(base.amount.minus(deductible.amount), coveragePct);
    if (!covered.gt(ZERO_AMOUNT)) {
      return new Rejection(ReasonCode.BELOW_DEDUCTIBLE, deductible.observations);
    }
    return new Adjusted(covered, deductible.observations);
  }
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { Decimal } from '../shared/decimal.ts';
import { Adjusted } from '../model/StepResults.ts';
import { Mark } from '../model/vocabulary.ts';
import { roundedComplementOf } from './rounding.ts';

export class ClaimFrequencyPenalty {
  /**
   * Con MAX_SINIESTROS_ANUAL o más siniestros liquidados previos en 365 días, reduce el cubierto.
   * @rule R-014
   * @rule R-022
   */
  apply(covered: Adjusted, priorLiquidatedClaims: number, parameters: BusinessParameters): Adjusted {
    if (Decimal.of(priorLiquidatedClaims).lt(parameters.maxAnnualClaims)) {
      return covered;
    }
    const reduced = roundedComplementOf(covered.amount, parameters.claimFrequencyPenaltyPct);
    return new Adjusted(reduced, covered.observations.add(Mark.CLAIM_FREQUENCY_PENALTY));
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { Adjusted, Rejection } from '../model/StepResults.ts';
import { Mark, ReasonCode } from '../model/vocabulary.ts';
import { ZERO_AMOUNT, toMoney } from './rounding.ts';

export class InsuredSumLimit {
  /**
   * Limita el cubierto a la suma asegurada remanente; sin remanente rechaza por SUMA_ASEGURADA_AGOTADA.
   * @rule R-015
   */
  apply(covered: Adjusted, sumInsured: Decimal, totalIndemnified: Decimal): Adjusted | Rejection {
    const remaining = toMoney(sumInsured.minus(totalIndemnified));
    if (!remaining.gt(ZERO_AMOUNT)) {
      return new Rejection(ReasonCode.INSURED_SUM_EXHAUSTED, covered.observations);
    }
    if (covered.amount.gt(remaining)) {
      return new Adjusted(remaining, covered.observations.add(Mark.INSURED_SUM_CAP));
    }
    return covered;
  }
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { Adjusted } from '../model/StepResults.ts';
import { Mark, PolicyBranch } from '../model/vocabulary.ts';
import { ZERO_AMOUNT, roundedPercentOf } from './rounding.ts';

export class WithholdingCalculator {
  /**
   * Retención impositiva (ramos distintos de VIDA con cubierto > UMBRAL_RETENCION). El importe devuelto es la retención.
   * @rule R-016
   * @rule R-022
   */
  calculate(covered: Adjusted, branch: string, parameters: BusinessParameters): Adjusted {
    if (!this.applies(covered, branch, parameters)) {
      return new Adjusted(ZERO_AMOUNT, covered.observations);
    }
    const withheld = roundedPercentOf(covered.amount, parameters.withholdingRatePct);
    return new Adjusted(withheld, covered.observations.add(Mark.WITHHOLDING_APPLIED));
  }

  /** @rule R-016 */
  private applies(covered: Adjusted, branch: string, parameters: BusinessParameters): boolean {
    return branch !== PolicyBranch.LIFE && covered.amount.gt(parameters.withholdingThreshold);
  }
}

import type { ClaimCase } from '../model/ClaimCase.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { Observations } from '../model/Observations.ts';
import { CalculatedAmounts, Rejection } from '../model/StepResults.ts';
import type { BaseAmountCalculator } from './BaseAmountCalculator.ts';
import type { DeductibleCalculator } from './deductible/DeductibleCalculator.ts';
import type { CoveredAmountCalculator } from './CoveredAmountCalculator.ts';
import type { ClaimFrequencyPenalty } from './ClaimFrequencyPenalty.ts';
import type { InsuredSumLimit } from './InsuredSumLimit.ts';
import type { WithholdingCalculator } from './WithholdingCalculator.ts';

/** Pipeline de cálculo de importes, en el orden del legacy. */
export class AmountCalculator {
  private readonly baseCalculator: BaseAmountCalculator;
  private readonly deductibleCalculator: DeductibleCalculator;
  private readonly coveredCalculator: CoveredAmountCalculator;
  private readonly frequencyPenalty: ClaimFrequencyPenalty;
  private readonly insuredSumLimit: InsuredSumLimit;
  private readonly withholdingCalculator: WithholdingCalculator;

  constructor(
    baseCalculator: BaseAmountCalculator,
    deductibleCalculator: DeductibleCalculator,
    coveredCalculator: CoveredAmountCalculator,
    frequencyPenalty: ClaimFrequencyPenalty,
    insuredSumLimit: InsuredSumLimit,
    withholdingCalculator: WithholdingCalculator,
  ) {
    this.baseCalculator = baseCalculator;
    this.deductibleCalculator = deductibleCalculator;
    this.coveredCalculator = coveredCalculator;
    this.frequencyPenalty = frequencyPenalty;
    this.insuredSumLimit = insuredSumLimit;
    this.withholdingCalculator = withholdingCalculator;
  }

  /**
   * El neto es una resta exacta (cubierto - retención), sin redondeo adicional.
   * @rule R-009
   * @rule R-010
   * @rule R-011
   * @rule R-012
   * @rule R-013
   * @rule R-014
   * @rule R-015
   * @rule R-016
   * @rule R-022
   */
  calculate(claim: ClaimCase, parameters: BusinessParameters, observations: Observations): CalculatedAmounts | Rejection {
    const base = this.baseCalculator.calculate(claim.claim.claimedAmount, claim.coverage.limit, observations);
    const deductible = this.deductibleCalculator.calculate(claim, base, parameters);
    const covered = this.coveredCalculator.calculate(base, deductible, claim.coverage.percentage);
    if (covered instanceof Rejection) {
      return covered;
    }
    const penalized = this.frequencyPenalty.apply(covered, claim.policy.priorLiquidatedClaims365d, parameters);
    const capped = this.insuredSumLimit.apply(penalized, claim.policy.sumInsured, claim.policy.totalIndemnified);
    if (capped instanceof Rejection) {
      return capped;
    }
    const withholding = this.withholdingCalculator.calculate(capped, claim.policy.branch, parameters);
    const net = capped.amount.minus(withholding.amount);
    return new CalculatedAmounts(
      base.amount,
      deductible.amount,
      capped.amount,
      withholding.amount,
      net,
      withholding.observations,
    );
  }
}

import type { ClaimCase } from '../model/ClaimCase.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
