import { ReasonCode, SettlementStatus } from '../model/vocabulary.ts';
import type { ReasonCodeValue, SettlementStatusValue } from '../model/vocabulary.ts';

export class ApprovalDecision {
  readonly status: SettlementStatusValue;
  readonly reason: ReasonCodeValue;

  constructor(status: SettlementStatusValue, reason: ReasonCodeValue) {
    this.status = status;
    this.reason = reason;
  }
}

export class ApprovalPolicy {
  private readonly fraudAlert: FraudAlertSpecification;

  constructor(fraudAlert: FraudAlertSpecification) {
    this.fraudAlert = fraudAlert;
  }

  /**
   * La alerta de fraude (R-017) tiene prioridad sobre el tope automático (R-018).
   * @rule R-017
   * @rule R-018
   */
  decide(claim: ClaimCase, parameters: BusinessParameters, netAmount: Decimal): ApprovalDecision {
    if (this.fraudAlert.isSatisfiedBy(claim, parameters)) {
      return new ApprovalDecision(SettlementStatus.PENDING_APPROVAL, ReasonCode.FRAUD_SUSPICION);
    }
    if (netAmount.gt(parameters.autoApprovalLimit)) {
      return new ApprovalDecision(SettlementStatus.PENDING_APPROVAL, ReasonCode.AUTO_LIMIT_EXCEEDED);
    }
    return new ApprovalDecision(SettlementStatus.APPROVED, ReasonCode.AUTOMATIC_SETTLEMENT);
  }
}

