/** Liquidación resultante de un siniestro. */
export class Settlement {
  readonly status: SettlementStatusValue;
  readonly reasonCode: ReasonCodeValue;
  readonly claimedAmount: Decimal;
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
  readonly observations: Observations;
  readonly settlementDate: DateOnly;
  readonly finalClaimStatus: ClaimFinalStatusValue;

  constructor(
    status: SettlementStatusValue,
    reasonCode: ReasonCodeValue,
    claimedAmount: Decimal,
    amounts: CalculatedAmounts,
    settlementDate: DateOnly,
  ) {
    this.status = status;
    this.reasonCode = reasonCode;
    this.claimedAmount = claimedAmount;
    this.baseAmount = amounts.base;
    this.deductibleAmount = amounts.deductible;
    this.coveredAmount = amounts.covered;
    this.withholdingAmount = amounts.withholding;
    this.netAmount = amounts.net;
    this.observations = amounts.observations;
    this.settlementDate = settlementDate;
    this.finalClaimStatus = finalClaimStatusFor(status);
  }

  /**
   * Liquidación rechazada: todos los importes en cero; el monto reclamado se registra.
   * @rule R-019
   * @rule R-020
   */
  static rejected(
    reason: ReasonCodeValue,
    observations: Observations,
    claimedAmount: Decimal,
    processDate: DateOnly,
    zeroAmounts: CalculatedAmounts,
  ): Settlement {
    void ZERO_AMOUNT;
    return new Settlement(SettlementStatus.REJECTED, reason, claimedAmount, zeroAmounts, processDate);
  }
}

