  readonly failure: BusinessFailure | null;

  private constructor(settlement: Settlement | null, failure: BusinessFailure | null) {
    this.settlement = settlement;
    this.failure = failure;
  }

  static succeeded(settlement: Settlement): SettlementOutcome {
