import { CalculatedAmounts, Rejection } from '../model/StepResults.ts';
import type { RegisteredClaimSpecification } from '../specifications/RegisteredClaimSpecification.ts';
import type { EligibilityPolicy } from './EligibilityPolicy.ts';
import type { AmountCalculator } from './AmountCalculator.ts';
import type { ApprovalPolicy } from './ApprovalPolicy.ts';
import { ZERO_AMOUNT } from './rounding.ts';

/** Servicio de dominio que orquesta la liquidación completa de un siniestro. */
export class ClaimSettlementService {
  private readonly registeredSpecification: RegisteredClaimSpecification;
  private readonly eligibility: EligibilityPolicy;
  private readonly calculator: AmountCalculator;
  private readonly approval: ApprovalPolicy;

  constructor(
    registeredSpecification: RegisteredClaimSpecification,
    eligibility: EligibilityPolicy,
    calculator: AmountCalculator,
    approval: ApprovalPolicy,
  ) {
    this.registeredSpecification = registeredSpecification;
    this.eligibility = eligibility;
    this.calculator = calculator;
    this.approval = approval;
  }

  /**
   * Comprueba que el siniestro esté REGISTRADO y que existan los parámetros; luego liquida.
   * @rule R-001
   * @rule R-023
   */
  process(claim: ClaimCase, parameterValues: ReadonlyMap<string, Decimal>): SettlementOutcome {
    if (!this.registeredSpecification.isSatisfiedBy(claim)) {
      return SettlementOutcome.failed(BusinessFailure.claimNotRegistered(claim.claimId, claim.claim.status));
    }
    const resolution = BusinessParameters.resolve(parameterValues);
    if (resolution.parameters === null) {
      return SettlementOutcome.failed(resolution.failure as BusinessFailure);
    }
    return SettlementOutcome.succeeded(this.settle(claim, resolution.parameters));
  }

  /**
   * Elegibilidad (R-002 a R-008), cálculo (R-009 a R-016) y decisión de aprobación (R-017, R-018).
   * @rule R-008
   * @rule R-017
   * @rule R-018
   * @rule R-019
   * @rule R-020
   */
  settle(claim: ClaimCase, parameters: BusinessParameters): Settlement {
    const eligibility = this.eligibility.evaluate(claim, parameters);
    if (eligibility instanceof Rejection) {
      return this.reject(claim, eligibility);
    }
    const amounts = this.calculator.calculate(claim, parameters, eligibility);
    if (amounts instanceof Rejection) {
      return this.reject(claim, amounts);
    }
    const decision = this.approval.decide(claim, parameters, amounts.net);
    return new Settlement(decision.status, decision.reason, claim.claim.claimedAmount, amounts, claim.claim.processDate);
  }

  /** @rule R-019 */
  private reject(claim: ClaimCase, rejection: Rejection): Settlement {
    const zeros = new CalculatedAmounts(
      ZERO_AMOUNT,
      ZERO_AMOUNT,
      ZERO_AMOUNT,
      ZERO_AMOUNT,
      ZERO_AMOUNT,
      Observations.empty(),
    );
    return Settlement.rejected(
      rejection.reason,
      rejection.observations,
      claim.claim.claimedAmount,
      claim.claim.processDate,
      this.withObservations(zeros, rejection.observations),
    );
  }

  /** @rule R-019 */
  private withObservations(zeros: CalculatedAmounts, observations: Observations): CalculatedAmounts {
    return new CalculatedAmounts(
      zeros.base,
      zeros.deductible,
      zeros.covered,
      zeros.withholding,
      zeros.net,
      observations,
    );
  }
}

