import { Decimal } from '../../../domain/shared/decimal.ts';
import { DateOnly } from '../../../domain/model/DateOnly.ts';

const TRUE_VALUES: readonly string[] = ['true', '1', 's', 'si', 'sí', 'y', 'yes'];

/** Lee y convierte los valores string de entrada, acumulando los problemas encontrados. */
export class InputReader {
  private readonly input: Record<string, string>;
  private readonly problems: string[];

  constructor(input: Record<string, string>) {
    this.input = input;
    this.problems = [];
  }

  get errors(): readonly string[] {
    return this.problems;
  }

  text(name: string): string {
    const raw = this.input[name];
    if (raw === undefined || raw === null) {
      this.problems.push(`Campo requerido: ${name}`);
      return '';
    }
    return String(raw).trim();
  }

  optionalText(name: string, fallback: string): string {
    const raw = this.input[name];
    return raw === undefined || raw === null ? fallback : String(raw).trim();
  }

  date(name: string): DateOnly {
    const parsed = DateOnly.parse(this.text(name));
    if (parsed === null) {
      this.problems.push(`Fecha inválida: ${name}`);
      return DateOnly.fromEpochDay(0);
    }
    return parsed;
  }

  money(name: string): Decimal {
    try {
      return Decimal.of(this.text(name)).setScale(2, 'HALF_UP');
    } catch {
      this.problems.push(`Decimal inválido: ${name}`);
      return Decimal.of('0.00');
    }
  }

  integer(name: string): number {
    const text = this.text(name);
    if (!/^-?\d+$/.test(text)) {
      this.problems.push(`Entero inválido: ${name}`);
      return 0;
    }
    return parseInt(text, 10);
  }

  boolean(name: string): boolean {
    return TRUE_VALUES.includes(this.text(name).toLowerCase());
  }
}

import { Decimal } from '../../../domain/shared/decimal.ts';

export class ParsedParameters {
  readonly values: ReadonlyMap<string, Decimal>;
  readonly problems: readonly string[];

  constructor(values: ReadonlyMap<string, Decimal>, problems: readonly string[]) {
    this.values = values;
    this.problems = problems;
  }
}

/** Interpreta 'CODIGO=valor' separados por ';', ',' o saltos de línea. */
export class ParameterTextParser {
  parse(text: string): ParsedParameters {
    const values = new Map<string, Decimal>();
    const problems: string[] = [];
    for (const entry of text.split(/[;,\n]+/)) {
      this.readEntry(entry.trim(), values, problems);
    }
    return new ParsedParameters(values, problems);
  }

  private readEntry(entry: string, values: Map<string, Decimal>, problems: string[]): void {
    if (entry === '') {
      return;
    }
    const separator = entry.indexOf('=');
    if (separator < 1) {
      problems.push(`Parámetro mal formado: ${entry}`);
      return;
    }
    const code = entry.substring(0, separator).trim().toUpperCase();
    try {
      values.set(code, Decimal.of(entry.substring(separator + 1).trim()));
    } catch {
      problems.push(`Valor de parámetro inválido: ${code}`);
    }
  }
}

