export class MappingResult {
  readonly request: SettleClaimRequest | null;
  readonly problems: readonly string[];

  constructor(request: SettleClaimRequest | null, problems: readonly string[]) {
    this.request = request;
    this.problems = problems;
  }
}

/** Adaptador de entrada: convierte el mapa de strings en tipos del dominio. */
export class ClaimInputMapper {
  map(input: Record<string, string>): MappingResult {
    const reader = new InputReader(input);
    const claim = this.readClaim(reader);
    const parsed = new ParameterTextParser().parse(reader.text('params'));
    const problems = [...reader.errors, ...parsed.problems];
    if (problems.length > 0) {
      return new MappingResult(null, problems);
    }
    return new MappingResult({ claim, parameterValues: parsed.values }, []);
  }

  private readClaim(reader: InputReader): ClaimCase {
    return {
      claimId: reader.optionalText('claim_id', 'N/A'),
      customerCategory: reader.text('customer_category'),
      claim: {
        status: reader.text('claim_status'),
        occurrenceDate: reader.date('occurrence_date'),
        reportDate: reader.date('report_date'),
        processDate: reader.date('process_date'),
        claimedAmount: reader.money('claimed_amount'),
      },
      policy: {
        status: reader.text('policy_status'),
        branch: reader.text('policy_branch'),
        startDate: reader.date('policy_start_date'),
        endDate: reader.date('policy_end_date'),
        sumInsured: reader.money('sum_insured'),
        deductibleType: reader.text('deductible_type'),
        deductibleValue: reader.money('deductible_value'),
        pendingPremium: reader.money('pending_premium'),
        priorLiquidatedClaims365d: reader.integer('prior_liquidated_claims_365d'),
        totalIndemnified: reader.money('total_indemnified'),
      },
      coverage: {
        code: reader.text('coverage_code'),
        found: reader.boolean('coverage_found'),
        limit: reader.money('coverage_limit'),
        percentage: reader.money('coverage_pct'),
        waitingDays: reader.integer('waiting_days'),
      },
    };
  }
}

