/** Adaptador de entrada: strings a dominio, ejecuta el caso de uso y devuelve strings. */
export class ClaimEntryAdapter {
  private readonly useCase: SettleClaimUseCase;
  private readonly mapper: ClaimInputMapper;

  constructor(useCase: SettleClaimUseCase, mapper: ClaimInputMapper) {
    this.useCase = useCase;
    this.mapper = mapper;
  }

  handle(input: Record<string, string>): Record<string, string> {
    const mapped = this.mapper.map(input);
    if (mapped.request === null) {
      return failureRecord(new BusinessFailure('INVALID_INPUT', mapped.problems.join(' | ')));
    }
    return outcomeRecord(this.useCase.execute(mapped.request));
  }
}

import { SettleClaimService } from './application/use-cases/SettleClaimService.ts';
import {
  CoverageContractedRule,
  OccurrenceWithinValidityRule,
  PolicyInForceRule,
  PremiumArrearsRule,
  ReportingDeadlineRule,
  WaitingPeriodRule,
} from './domain/eligibility/eligibilityRules.ts';
import { AmountCalculator } from './domain/services/AmountCalculator.ts';
