import { InMemorySettlementAudit } from './infrastructure/adapters/out/InMemorySettlementAudit.ts';

/** Composition root: ensambla dependencias y delega al caso de uso. Sin lógica de negocio. */
export function execute(input: Record<string, string>): Record<string, string> {
  const eligibility = new EligibilityPolicy([
    new PolicyInForceRule(),
    new OccurrenceWithinValidityRule(),
    new ReportingDeadlineRule(),
    new CoverageContractedRule(),
    new WaitingPeriodRule(),
    new PremiumArrearsRule(),
  ]);
  const calculator = new AmountCalculator(
    new BaseAmountCalculator(),
    new DeductibleCalculator(
      new FixedDeductibleStrategy(),
      new PercentageDeductibleStrategy(),
      new VipDeductibleDiscount(),
    ),
    new CoveredAmountCalculator(),
    new ClaimFrequencyPenalty(),
    new InsuredSumLimit(),
    new WithholdingCalculator(),
  );
  const settlementService = new ClaimSettlementService(
    new RegisteredClaimSpecification(),
    eligibility,
    calculator,
    new ApprovalPolicy(new FraudAlertSpecification()),
  );
  const useCase = new SettleClaimService(settlementService, new InMemorySettlementAudit());
  return new ClaimEntryAdapter(useCase, new ClaimInputMapper()).handle(input);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/index.ts';

const PARAMS =
  'DIAS_MAX_DENUNCIA=30;DIAS_MAX_DENUNCIA_VIDA=365;DEDUCIBLE_MINIMO=100;PCT_DESCUENTO_DED_VIP=50;' +
  'TOLERANCIA_MORA_VIP=500;MAX_SINIESTROS_ANUAL=3;PCT_PENALIZACION_SINIEST=10;UMBRAL_RETENCION=10000;' +
  'TASA_RETENCION=2;TOPE_AUTO_APROBACION=50000;DIAS_ALERTA_FRAUDE=15;PCT_ALERTA_FRAUDE=80';

function baseInput(): Record<string, string> {
  return {
    claim_id: '1',
    process_date: '2026-03-10',
    claimed_amount: '5000.00',
    occurrence_date: '2026-03-01',
    report_date: '2026-03-05',
    coverage_code: 'COL',
    claim_status: 'REGISTRADO',
    policy_status: 'VIGENTE',
    policy_branch: 'AUTO',
    policy_start_date: '2026-01-01',
    policy_end_date: '2026-12-31',
    sum_insured: '100000.00',
    deductible_type: 'FIJO',
    deductible_value: '200.00',
    pending_premium: '0.00',
    customer_category: 'ESTANDAR',
    coverage_found: 'true',
    coverage_limit: '10000.00',
    coverage_pct: '80.00',
    waiting_days: '0',
    prior_liquidated_claims_365d: '0',
    total_indemnified: '0.00',
    params: PARAMS,
  };
}

test('aprueba automáticamente una liquidación estándar', () => {
  const out = execute(baseInput());
  assert.equal(out.status, 'APROBADA');
  assert.equal(out.reason_code, 'LIQUIDACION_AUTOMATICA');
  assert.equal(out.covered_amount, '3840.00');
  assert.equal(out.net_amount, '3840.00');
  assert.equal(out.claim_final_status, 'LIQUIDADO');
});

test('rechaza una póliza no vigente con importes en cero', () => {
  const out = execute({ ...baseInput(), policy_status: 'CANCELADA' });
  assert.equal(out.status, 'RECHAZADA');
  assert.equal(out.reason_code, 'POLIZA_NO_VIGENTE');
  assert.equal(out.net_amount, '0.00');
  assert.equal(out.claim_final_status, 'RECHAZADO');
});

test('devuelve ORA-20001 si el siniestro no está REGISTRADO', () => {
  const out = execute({ ...baseInput(), claim_status: 'LIQUIDADO' });
  assert.equal(out.status, 'ERROR');
  assert.equal(out.error_code, 'ORA-20001');
});
